const staticData = $getWorkflowStaticData('node');

const materials = [
  { name: "Cement (OPC)", base: 1450, unit: "per bag" },
  { name: "Steel (Grade 60)", base: 285000, unit: "per ton" },
  { name: "Bricks", base: 14, unit: "per piece" },
  { name: "Sand", base: 3200, unit: "per 100 cft" },
  { name: "Crush/Gravel", base: 4100, unit: "per 100 cft" },
  { name: "Paint (Emulsion)", base: 1850, unit: "per gallon" },
  { name: "Wood (Deodar)", base: 3800, unit: "per cft" },
  { name: "Tiles (Ceramic)", base: 95, unit: "per sq ft" }
];

const today = new Date().toISOString().slice(0, 10);
const oldPrices = staticData.oldPrices || {};
const newPrices = {};
const changes = [];

materials.forEach(m => {
  // Simulated daily fluctuation - replace with a real HTTP Request node output when you have a live source
  const price = m.base + Math.floor(Math.random() * 61) - 30;
  newPrices[m.name] = price;
  const old = oldPrices[m.name];
  if (old !== undefined && old !== price) {
    const direction = price > old ? 'UP' : 'DOWN';
    changes.push(`${m.name}: ${old} -> ${price} (${direction})`);
  }
});

staticData.oldPrices = newPrices;

const priceListText = materials.map(m => `${m.name}: PKR ${newPrices[m.name].toLocaleString()} (${m.unit})`).join('\n');
const changesText = changes.length ? changes.join('\n') : 'No price changes since last check.';

return [{
  json: {
    date: today,
    priceList: priceListText,
    changes: changesText
  }
}];

const weather = $input.first().json;

const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().slice(0, 10);

const dates = weather.daily.time;
const probs = weather.daily.precipitation_probability_max;
let rainChance = 0;
for (let i = 0; i < dates.length; i++) {
  if (dates[i] === tomorrowStr) { rainChance = probs[i]; break; }
}

// Sample site schedule - replace this block with a Google Sheets 'Read Rows' node output
const sites = ["DHA Phase 6 Site", "Bahria Town Block C", "F-10 Residency"];
const tasks = [
  { name: "Concrete Pouring", outdoor: true },
  { name: "Roofing Work", outdoor: true },
  { name: "Excavation", outdoor: true },
  { name: "Electrical Wiring", outdoor: false },
  { name: "Steel Fixing", outdoor: true },
  { name: "Painting (Exterior)", outdoor: true }
];

const scheduledTomorrow = [];
for (let i = 0; i < 4; i++) {
  const site = sites[Math.floor(Math.random() * sites.length)];
  const task = tasks[Math.floor(Math.random() * tasks.length)];
  if (task.outdoor) scheduledTomorrow.push(`${site} - ${task.name}`);
}

const atRisk = rainChance >= 50 ? scheduledTomorrow : [];
const atRiskText = atRisk.length ? atRisk.join('\n') : 'No outdoor tasks at risk tomorrow.';

return [{
  json: {
    tomorrow: tomorrowStr,
    rainChance: rainChance,
    atRiskTasks: atRiskText
  }
}];

// Sample data - replace this block with a Google Sheets 'Read Rows' node output
const companies = [
  "ABC Electrical Works", "Metro Plumbing Co", "Skyline Steel Fabricators",
  "Prime Concrete Solutions", "National Scaffolding Services",
  "Elite HVAC Contractors", "Al-Rehman Glass and Aluminum", "Modern Interiors Pvt Ltd"
];
const docTypes = ["Insurance Certificate", "Safety Compliance License", "Trade License", "Tax Registration"];
const offsets = [-15, -5, 3, 7, 15, 25, 45, 60, -2, 10];

const today = new Date();
today.setHours(0, 0, 0, 0);
const results = [];

companies.forEach((company, idx) => {
  const docType = docTypes[Math.floor(Math.random() * docTypes.length)];
  const offset = offsets[idx % offsets.length];
  const expiry = new Date(today);
  expiry.setDate(expiry.getDate() + offset);
  const daysLeft = offset;

  if (daysLeft <= 30) {
    let message = daysLeft < 0
      ? `expired ${Math.abs(daysLeft)} day(s) ago`
      : (daysLeft === 0 ? 'expires today' : `expires in ${daysLeft} day(s)`);

    results.push({
      name: company,
      email: 'REPLACE_WITH_REAL_EMAIL@example.com',
      docType: docType,
      expiryDate: expiry.toISOString().slice(0, 10),
      message: message
    });
  }
});

return results.map(r => ({ json: r }));
